import itertools

def check_coloring(N, K, coloring_func):
    """
    Checks the constraint for a given N, K, and coloring function.
    Returns (True/False, set_Z_sets, set_X_sets, set_Y_sets)
    """
    all_colors = range(K)

    # 1. Generate all colors in the cube
    colors = {}
    for i in range(N):
        for j in range(N):
            for k in range(N):
                colors[(i, j, k)] = coloring_func(i, j, k)

    # 2. Analyze Z-slices (fixed k)
    Z_sets = set()
    for k0 in range(N):
        slice_colors = set()
        for i in range(N):
            for j in range(N):
                slice_colors.add(colors[(i, j, k0)])
        Z_sets.add(frozenset(slice_colors))

    # 3. Analyze X-slices (fixed i)
    X_sets = set()
    for i0 in range(N):
        slice_colors = set()
        for j in range(N):
            for k in range(N):
                slice_colors.add(colors[(i0, j, k)])
        X_sets.add(frozenset(slice_colors))

    # 4. Analyze Y-slices (fixed j)
    Y_sets = set()
    for j0 in range(N):
        slice_colors = set()
        for i in range(N):
            for k in range(N):
                slice_colors.add(colors[(i, j0, k)])
        Y_sets.add(frozenset(slice_colors))

    # 5. Check the constraint: Every Z-set must be in X_sets AND Y_sets

    # The constraint is: For ANY Z-slice S_Z(k0), C(S_Z(k0)) MUST appear in some X-slice S_X(i0) AND some Y-slice S_Y(j0).
    for Z_set in Z_sets:
        if Z_set not in X_sets or Z_set not in Y_sets:
            # Constraint failed
            return False, Z_sets, X_sets, Y_sets

    return True, Z_sets, X_sets, Y_sets

